insert into project_types (slug, display_name, params, sort_order) values ('bathroom-remodel', 'Bathroom remodel', '[{"name":"cosmetic_only","type":"boolean","label":"only finish work: paint, tile, flooring, cabinets, countertops"},{"name":"replaces_fixtures_in_place","type":"boolean","label":"replaces fixtures or appliances in their existing locations"},{"name":"mechanical_work","type":"boolean","label":"includes exhaust fan, range hood, or other ducted ventilation work"},{"name":"moves_or_adds_plumbing","type":"boolean","label":"moves or adds plumbing"},{"name":"electrical_work","type":"boolean","label":"includes electrical work"},{"name":"structural_changes","type":"boolean","label":"changes walls or structure"}]'::jsonb, 12);
